console.log(`   ${P.map((p, k) => `${k}:${p || '>2^' + (LAGS - 1)}`).join(' ')}`);
console.log(`m_k (minimal period of the driver g_k):`);
console.log(`   ${M.map((p, k) => `${k}:${p || '>2^' + (LAGS - 1)}`).join(' ')}`);
