console.log(`depths whose minimal period is covered by >= 2 full periods in ${N} rows: ${certified} of ${W}`);

// ------------------------------------------------------------- the criterion
{
  let bad = 0, drop = 0, rows = [];
  for (let k = 2; k < W; k++) {
    if (!P[k] || !P[k - 1] || !P[k - 2] || !M[k]) continue;
    const L = Math.max(P[k - 1], P[k - 2]);
