    if (!ok) bad++;
    if (P[k] < L) drop++;
    if (tel !== wt) { console.log(`   TELESCOPE MISMATCH at k=${k}`); bad++; }
    rows.push(`${k}: P=${P[k]} L=${L} m=${M[k]} wt=${wt} zeros=${zeros} (${(zeros / L).toFixed(3)}) halves=${zLow}/${zHigh}${zLow === zHigh ? ' EQUAL' : ''} marg=${marg} (${(marg / L).toFixed(3)})${ok ? '' : ' <<< FAILS'}`);
  }
